<template><div class="page"><div class="page-header"><h2>合同管理</h2></div><el-card shadow="never"><el-table :data="items" v-loading="loading" stripe size="small" highlight-current-row @row-click="open"><el-table-column prop="htbh" label="合同编号" width="120"/><el-table-column prop="years" label="年份" width="60"/><el-table-column label="合同属性" width="80"><template #default="{row}">{{ bsLabel(row.busityp) }}</template></el-table-column><el-table-column label="费用类型" width="80"><template #default="{row}">{{ ftLabel(row.feetyp) }}</template></el-table-column><el-table-column label="签订状态" width="80"><template #default="{row}"><el-tag :type="row.qdis==='1'?'success':'info'" size="small">{{ row.qdis==='1'?'已签':'未签' }}</el-tag></template></el-table-column><el-table-column prop="htamount" label="合同金额" width="110" align="right"><template #default="{row}">{{ row.htamount?'¥'+Number(row.htamount).toLocaleString():'-' }}</template></el-table-column><el-table-column label="有效期" width="180"><template #default="{row}">{{ row.yxqfrom||'-' }} ~ {{ row.yxqto||'-' }}</template></el-table-column><el-table-column prop="htbgr" label="保管人" width="80"/></el-table><AppPagination v-model:current-page="page" v-model:page-size="perPage" :total="total" style="margin-top:12px;justify-content:flex-end"/></el-card><el-dialog :title="'合同 — '+(detail?.htbh||'')" v-model="drawer" width="550px"><template v-if="detail"><el-descriptions :column="2" border size="small"><el-descriptions-item label="合同编号">{{ detail.htbh }}</el-descriptions-item><el-descriptions-item label="年份">{{ detail.years||'-' }}</el-descriptions-item><el-descriptions-item label="合同属性">{{ bsLabel(detail.busityp) }}</el-descriptions-item><el-descriptions-item label="费用类型">{{ ftLabel(detail.feetyp) }}</el-descriptions-item><el-descriptions-item label="区域">{{ className(detail.classcd) }}</el-descriptions-item><el-descriptions-item label="签订状态">{{ detail.qdis==='1'?'已签':'未签' }}</el-descriptions-item><el-descriptions-item label="签订日期">{{ detail.qdda